"""Render docs/evaluation_report.md from measured evaluation results (no hand-typed numbers)."""


def _f(v, pct: bool = False, nd: int = 3) -> str:
    if v is None:
        return "n/a"
    return f"{v:.1%}" if pct else f"{v:.{nd}f}"


def render_report(r: dict) -> str:
    ds, fc, an = r["dataset"], r["forecast"], r["anomaly"]
    lines = [
        "# Evaluation Report",
        "",
        "> Generated by `scripts/run_evaluation.py` from measured runs. **All results are on fully synthetic "
        "data** (seed {seed}, {days} days, {start} to {end}); they say nothing about performance on real "
        "customer traffic.".format(seed=ds["seed"], days=ds["days"], start=ds["start_date"], end=ds["end_date"]),
        "",
        f"Splits (chronological): train {ds['splits']['train'][0]}..{ds['splits']['train'][1]}, "
        f"validation {ds['splits']['validation'][0]}..{ds['splits']['validation'][1]}, "
        f"test {ds['splits']['test'][0]}..{ds['splits']['test'][1]}.",
        "",
        "## Forecasting (daily cost, MYR)",
        "",
        f"**Shipped model:** `{fc['selection']['chosen']}`. {fc['selection']['reason']}.",
        "",
        f"Test backtest: {len(fc['test']['origins'])} origins ({', '.join(fc['test']['origins'])}), "
        f"horizon {fc['test']['horizon_days']} days, retrained per origin. Workspace-level daily totals:",
        "",
        "| Model | MAE | RMSE | WAPE | sMAPE | WAPE h=1 | WAPE h=2-7 | WAPE h=8-14 |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for m, s in fc["test"]["scores"].items():
        w = s["workspace_daily"]
        lines.append(
            f"| {m} | {_f(w['mae'])} | {_f(w['rmse'])} | {_f(w['wape'])} | {_f(w['smape'])} | "
            f"{_f(s['workspace_daily_h1']['wape'])} | {_f(s['workspace_daily_h2_7']['wape'])} | "
            f"{_f(s['workspace_daily_h8_14']['wape'])} |"
        )
    lines += [
        "",
        "Supplementary segment-level WAPE excluding injected-event days (labels used only for scoring): "
        + ", ".join(
            f"{m} {_f(s['segment_daily_excluding_event_days']['wape'])}" for m, s in fc["test"]["scores"].items()
        ),
    ]
    lines += ["", "Validation (selection) workspace WAPE: " + ", ".join(
        f"{m} {_f(s['workspace_daily']['wape'])}" for m, s in fc["validation"]["scores"].items())]  # fmt: skip
    cov = fc["test"]["interval_coverage"]
    lines += [
        "",
        f"Prediction intervals (nominal {cov['nominal']:.0%}, relative residual quantiles from validation): "
        f"test coverage {_f(cov['segment_daily'], True)} for segment-days, "
        f"{_f(cov['cumulative_total'], True)} for cumulative workspace totals.",
    ]
    ov = fc["overrun_classification"]
    if ov.get("status") == "ok":
        lines += [
            "",
            f"### Month-end budget overrun ({ov['n_origins']} daily origins, months {ov['months']})",
            "",
            "| Budget | Positives / negatives | Central precision | Central recall | Lower-bound precision | "
            "Upper-bound recall |",
            "|---|---|---|---|---|---|",
        ]
        for b, v in ov["budgets"].items():
            lines.append(
                f"| RM{b} | {v['positives']} / {v['negatives']} | {_f(v['central_forecast']['precision'])} | "
                f"{_f(v['central_forecast']['recall'])} | {_f(v['high_confidence_lower_bound']['precision'])} | "
                f"{_f(v['possible_upper_bound']['recall'])} |"
            )
        e = ov["month_end_abs_pct_error"]
        lines += [
            "",
            f"Month-end absolute % error: {_f(e['all'], True)} overall, {_f(e['days_left_gt_14'], True)} with >14 "
            f"days left, {_f(e['days_left_le_14'], True)} with <=14 days left. Interval coverage "
            f"{_f(ov['month_end_interval_coverage'], True)}. {ov['caveat']}",
        ]

    t = an["splits"]["test"]
    c = an["chosen_config"]
    lines += [
        "",
        "## Anomaly detection (application-day)",
        "",
        f"Methods: {'; '.join(an['methods'])}. Chosen on validation: z >= {c['z_threshold']}, IsolationForest "
        f"quantile {c['if_quantile']}, impact floor RM{c['impact_floor_myr']:.2f}.",
        "",
        "| Split | Precision | Recall | F1 | FPR | False alerts / 30 days | Event recall | Mean delay (days) | "
        "Benign promos alerted |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for name, s in an["splits"].items():
        d = s["day_level"]
        lines.append(
            f"| {name} | {_f(d['precision'])} | {_f(d['recall'])} | {_f(d['f1'])} | {_f(d['false_positive_rate'])} | "
            f"{_f(s['false_alerts_per_30_days'], nd=2)} | {_f(s['event_recall'])} | "
            f"{_f(s['mean_detection_delay_days'], nd=1)} | {s['benign_promotions']['alerted']}/"
            f"{s['benign_promotions']['total']} |"
        )
    cm = t["confusion_matrix"]
    lines += [
        "",
        f"Test confusion matrix (days): TP {cm['tp']}, FP {cm['fp']}, FN {cm['fn']}, TN {cm['tn']}.",
        "",
        "Test events:",
        "",
        "| Event | Type | App | Expected | Detected | Delay | Reasons |",
        "|---|---|---|---|---|---|---|",
    ]
    for ev in t["events"]:
        lines.append(
            f"| {ev['event_id']} | {ev['kind']} | {ev['app_id']} | {ev['alert_expected']} | "
            f"{'yes' if ev['detected'] else 'no'} | {ev['detection_delay_days'] if ev['detected'] else '-'} | "
            f"{', '.join(ev['reason_codes']) or '-'} |"
        )
    lines += ["", "Notes:"] + [f"- {n}" for n in an["notes"]]
    c = r.get("cache")
    if c:
        lines += (
            [
                "",
                "## Safe FAQ cache (labelled query set)",
                "",
                f"Model {c['model']}, threshold {c['threshold']}, margin {c['margin']}, plus the deterministic safety gate "
                "and key-term guard.",
                "",
                f"- Accepted hits: {c['accepted_hits']} of {c['n']} queries; **hit precision {_f(c['hit_precision'])}**; "
                f"false hits {c['false_hits']} (adversarial false hits {c['adversarial_false_hits']}).",
                f"- Positive coverage {_f(c['positive_coverage'])} ("
                + ", ".join(f"{g}: {v['correct_hits']}/{v['n']}" for g, v in c["by_group"].items())
                + ").",
                f"- Decision latency: median {c['latency_ms']['median']:.2f} ms, p95 {c['latency_ms']['p95']:.2f} ms.",
                f"- Without the safety gate (embedding only): hit precision "
                f"{_f(c['ablation_without_safety_gate']['hit_precision'])}, false hits "
                f"{c['ablation_without_safety_gate']['false_hits']}.",
                "",
                "| Threshold | Hit precision | Positive coverage | False hits |",
                "|---|---|---|---|",
            ]
            + [
                f"| {s['threshold']} | {_f(s['hit_precision'])} | {_f(s['positive_coverage'])} | {s['false_hits']} |"
                for s in c["threshold_sweep"]
            ]
            + ["", f"_{c['caveat']}_"]
        )
    sim = r.get("simulator")
    if sim:
        fb, orc = sim["forecast_based"], sim["oracle_actual_units"]
        lines += [
            "",
            f"## What-if simulator vs counterfactual truth ({sim['window'][0]}..{sim['window'][1]})",
            "",
            f"True net savings from caching (synthetic potential outcomes): RM{sim['true_net_savings_myr']:.2f} "
            f"(gross RM{sim['true_gross_avoided_myr']:.2f} - overhead RM{sim['true_overhead_myr']:.2f}).",
            "",
            f"- Simulator on the forecast (as in production): RM{fb['estimate_myr']:.2f}, error "
            f"RM{fb['abs_error_myr']:.2f} ({_f(fb['pct_error'], True)}).",
            f"- Simulator on actual units (isolates assumption error): RM{orc['estimate_myr']:.2f}, error "
            f"RM{orc['abs_error_myr']:.2f} ({_f(orc['pct_error'], True)}).",
            f"- {sim['note']}",
        ]
    lines += [
        "",
        "## Limitations",
        "",
        "- Synthetic data follows the generator's assumptions (see `dataset_manifest.json`); real traffic will differ.",
        "- Intervals are empirical and assume validation-period error behaviour persists; coverage degrades under"
        " distribution shift.",
        "- Anomaly explanations are diagnostic correlations, not causal findings.",
        "",
    ]
    return "\n".join(lines)
